import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent: answers customers' questions about their orders and remembers the conversation. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date and tracking code.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so. ' +
    'Use the order id the customer gave you earlier in the conversation when they refer back to it.',
  tools: [lookupOrder],
});
